  hDist: ['Distancia = velocidad · tiempo. Cada hora recorre lo mismo: suma tantas horas como haya.', 'Distància = velocitat · temps. Cada hora recorre el mateix: suma tantes hores com n’hi haja.', 'Distance = speed · time. It covers the same each hour: add it once for each hour.'],
  hVel: ['En la balanza, v · {t} pesa lo mismo que la distancia. Divide la distancia entre {t}.', 'En la balança, v · {t} pesa el mateix que la distància. Divideix la distància entre {t}.', 'On the balance, v · {t} weighs the same as the distance. Divide the distance by {t}.'],
  hTime: ['En la balanza, {v} · t pesa lo mismo que la distancia. Divide la distancia entre {v}.', 'En la balança, {v} · t pesa el mateix que la distància. Divideix la distància entre {v}.', 'On the balance, {v} · t weighs the same as the distance. Divide the distance by {v}.'],
  qConc: ['Disolvemos {m} g de sal en {V} litros de agua. ¿Cuántos gramos hay en cada litro?', 'Dissolem {m} g de sal en {V} litres d’aigua. Quants grams hi ha en cada litre?', 'We dissolve {m} g of salt in {V} litres of water. How many grams are there in each litre?'],
  hConc: ['Reparte los gramos entre los {V} litros a partes iguales: es la concentración en g/L.', 'Reparteix els grams entre els {V} litres a parts iguals: és la concentració en g/L.', 'Share the grams equally between the {V} litres: that is the concentration in g/L.'],
